import math
import random
import itertools
import numpy as np
from scipy.optimize import minimize

SQRT3 = math.sqrt(3.0)
_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _area(p, q, r):
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in itertools.combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _random_point():
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p):
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n=11):
    pts = []
    for _ in range(n):
        pts.append(_random_point())
    return np.array(pts)

def _optimize(pts, max_iter=10000):
    def objective(x):
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)

    res = minimize(
        objective,
        pts.ravel(),
        method='Nelder-Mead',
        options={'maxiter': max_iter, 'fatol': 1e-8}
    )
    optimized = res.x.reshape((-1, 2))
    for i in range(len(optimized)):
        optimized[i] = _project_to_simplex(optimized[i])
    return optimized

def find_points(seed=None):
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)

    best_pts = None
    best_score = 0

    for _ in range(5):
        pts = _initial_configuration(11)
        pts = _optimize(pts)
        score = _min_triangle_area(pts)
        if score > best_score:
            best_score = score
            best_pts = pts

    return [(float(x), float(y)) for x, y in best_pts]
